from time import sleep
from taf.ue import ue as taf_ue
from robot.libraries.BuiltIn import BuiltIn
from ta_ue_plugin_android.uepc.ue_manager_exceptions import IperfServerStuckException, CannotAttachError
from taf.ue.rpc.jsonrpc.rpc import RpcError

from taf.rfrl.l3_call.logger.l3_call_logger import log_input_and_output, log_result, log_to_console
from taf.rfrl.l3_call.ue.test_pc import TestPc
from taf.rfrl.l3_call.ue.exceptions import NoDataTransfer, UnexpectedError, IncorrectWidgetText


class Ue(object):
    def __init__(self, ue, ue_index):
        self.tl_ue = ue
        self.taf_ue = taf_ue()
        self.alias = "UE_FOR_TA_{}".format(ue_index)
        self.index = ue_index
        self.serial_number = self._get_ue_details().serial_number
        self.capabilities = self._get_ue_details().capabilities[0]
        self.ue_reservation = False
        self.test_pc = None
        self.cell = None
        self.apn = None
        self.network_mode = None
        self.ue_info = None
        self._device_model = None

    @property
    def device_model(self):
        if not self._device_model:
            self._device_model = self.taf_ue.get_ue_info(self.alias, 'device_model')

        return self._device_model

    @log_input_and_output
    def reservation(self, reboot=False):
        """
        Performs UE reservation before further operations. Key steps:
            - UE require - connect to UE if alias has not been assigned before
            - UE reboot - reboot ue: 'ute' - using ute library or 'adb' - adb command (skipped if reboot=False)
            - trial UE attach/detach
            - UE info retrieval
        """
        if not self.ue_reservation:
            self.require_ue(capabilities=self.capabilities)

        if reboot == "adb":
            self.adb_reboot()
        if reboot == "ute":
            self.reboot()

        try:
            self.attach(attach_should_be_possible=True)
            self.ue_info = self._get_ue_info()
            self.apn = self._get_apn_from_ue_info(self.ue_info.get('ips')) if self.ue_info.get('ips') else None
            self.network_mode = self.ue_info.get("preferred_net_mode")
        finally:
            self.detach()

        log_result(f"UE reservation completed for UE with serial number: {self.serial_number}\nUE info:\n{self.ue_info}")

    def setup_ue_pc(self):
        """
        Establishes connection to the test_pc using
        credentials stored in tl_ue attribute.
        """
        try:
            self.test_pc = TestPc(
                hostname=self.tl_ue.ssh_connection_details.addr,
                username=self.tl_ue.ssh_connection_details.username,
                password=self.tl_ue.ssh_connection_details.password,
            )
        except AttributeError:
            self.test_pc = TestPc(
                hostname=self.tl_ue.ue_pc_address,
                username=self.tl_ue.ue_pc_login,
                password=self.tl_ue.ue_pc_password,
            )

    def lock(self, timeout_sec, sleep_between_tries_sec=10):
        """
        Waits for ue and create own .lock file.
        :param timeout_sec: Waiting time for ue to be available [in seconds]
        :type timeout_sec: int
        :param sleep_between_tries_sec: Waiting time between tries [in seconds]
        :type sleep_between_tries_sec: int
        :raises ValueError exception when there is file reading error
        :raises EnvironmentError when there is not ue available
        """
        self.test_pc.lock(self.alias, timeout_sec, sleep_between_tries_sec)

    def unlock(self):
        """
        Removes .lock file and unlocks ue.
        :raises ValueError if .lock file removing failed.
        """
        self.test_pc.unlock(self.alias)

    def reboot(self, timeout_sec=90):
        """
        Reboots ue via TAF UE
        Sleep of 60 seconds is provided for UE to become operational
        again after reboot.

        :param timeout_sec: Waiting time for ue reboot [in seconds]
        :type timeout_sec: int
        """
        self.taf_ue.reboot_ue(self.alias, timeout=timeout_sec)
        sleep(60)

    def adb_reboot(self):
        """
        Reboots ue via ADB
        Sleep of 60 seconds is provided for UE to become operational
        again after reboot.
        :raises ValueError exception while executing removal command
        """
        self.test_pc.reboot()
        sleep(60)

    def require_ue(self, capabilities):
        """
        Prepares mandatory test environment.

        :param capabilities: Settings required by ue architecture.
                            Capabilities that UE has. like:
                            - REAL_UE
                            - REAL_ANDROID_UE
        :type capabilities: str
        """

        self.taf_ue.require_ue(ue_alias=self.alias, capabilities=capabilities)
        self.ue_reservation = True
        log_to_console("Alias {} assigned to UE {}.".format(self.alias, self.serial_number))

    def attach(self, attach_should_be_possible, timeout=40):
        """
        Attach ue

        :param attach_should_be_possible: True if attach is expected to succeed, False if no attach is expected
        :type attach_should_be_possible: bool
        :param timeout: Timeout for attach operation in seconds
        :type timeout: int
        :raises UnexpectedError when an unexpected Rpc error occurs during attach procedure
        """
        extra_params = self._get_extra_params_for_ue_attach()

        if not attach_should_be_possible:
            try:
                self.taf_ue.attach_ue(self.alias, timeout=timeout, **extra_params)
            except CannotAttachError as e:
                log_result(str(e))
            except RpcError as e:
                if "CannotAttachError" not in str(e):
                    raise UnexpectedError("Unexpected error occurred when trying to attach"
                                          ", expected error connected to attach (CannotAttachError), "
                                          "got {}".format(str(e)))
                log_result(str(e))
        else:
            self.taf_ue.attach_ue(self.alias, timeout=timeout, **extra_params)
            attached_cell_id = self.get_cell_id()
            log_result(f"Attach succeeded to cell ID: {attached_cell_id}")

    def set_apn(self, apn, apn_settings_path=None):
        """
        Sets attribute that holds Access Point Name and changes APN on UE if arg `apn_settings_path` provided.
        Changes APN on UE available only for Android!

        :param apn: Access Point Name e.g '5GSAWRO'
        :type apn: str
        :param apn_settings_path: Path to the APN settings on UE, e.g. 'Network & internet,Mobile network,SIM 1,Access Point Names'
        :type apn_settings_path: str
        :raises TypeError when changing the APN on a UE other than Android.
        """
        if apn_settings_path:
            if "Android" not in str(type(self.tl_ue)):
                raise TypeError("Changing APN on UE is available only for Android!")
            log_to_console(f"Changing APN on UE with SN: {self.serial_number} to '{apn}' using path: '{apn_settings_path}'")
            self.taf_ue.change_apn(self.alias, apn_name=apn, labels_to_apn_settings=apn_settings_path)

        self.apn = apn
        log_to_console("APN set successfully")

    def detach(self, timeout=60):
        """
        Detach ue
        """
        self.taf_ue.detach_ue(self.alias, timeout=timeout)

    def get_cell_id(self):
        """
        Gets ue cell id from ue info
        :return: ue cell id info
        :rtype: str
        """
        return self.taf_ue.get_ue_info(self.alias, 'CELL_ID')

    def get_ue_ip(self):
        """
        Gets ue ip from ue info
        :return: ue ip
        :rtype: str
        """
        return self.taf_ue.get_ue_info(self.alias, 'IP')

    def start_data_transfer(self, direction, duration, throughput, protocol, udp_buffer, **kwargs):
        """
        Starts data transfer
        :param direction: Transfer direction: can be downloaded or uploaded, i.e. 'dl' or 'ul'
        :type direction: str
        :param duration: Duration of data transferring, i.e. '300s'
        :type duration: str
        :param throughput: Amount of data transfer throughput, i.e. '558 Mbits/sec'
        :type throughput: str
        :param protocol: Data transfer protocol, can be only 'tcp', or 'udp'
        :type protocol: str
        :param udp_buffer: Monitoring data buffer
        :type udp_buffer: str
        :param kwargs: kwargs to start_data_transfer:
            :param apn: Access Point Name, i.e. '5GSAWRO'
            :type apn: str
            :param linux_congestion: option "-Z" for iperf2. TCP congestion algorithm (Linux and FreeBSD only)
            :type linux_congestion: str
        """
        dt_name = self._get_ue_data_transfer_alias(direction=direction)
        filtered_kwargs = {key: value for key, value in kwargs.items() if value is not None}

        self.taf_ue.start_data_transfer(
            dt_name=dt_name,
            ue_alias=self.alias,
            direction=direction,
            duration=duration,
            throughput=throughput,
            protocol=protocol,
            packet_size='1300',
            buffer=udp_buffer,
            **filtered_kwargs
        )
        return dt_name

    def stop_data_transfer(self, dt_name):
        """
        Stops data transfer
        :param dt_name: Data transfer alias
        :type dt_name: str
        """
        self.taf_ue.stop_data_transfer(dt_name=dt_name)

    def await_data_transfer_finish(self, dt_name):
        """
        Awaits data transfer finish
        :param dt_name: Data transfer alias
        :type dt_name: str
        """
        self.taf_ue.await_data_transfer_finish(dt_name=dt_name)

    def check_data_transfer_is_alive(self, dt_name):
        """
        Checks if data transfer between client and server is progressing.

        :param dt_name: Data transfer alias
        :type dt_name: str
        :raises NoDataTransfer exception when there is no data transfer detection.
        """
        try:
            self.taf_ue.check_data_transfer_is_alive(dt_name=dt_name)
        except IperfServerStuckException:
            raise NoDataTransfer("There is no data transfer running between client and server!")

    def verify_average_throughput_with_deviation_using_iperf(self, dt_name, throughput, deviation):
        """
        Verifies average throughput with deviation
        :param dt_name: Data transfer alias
        :type dt_name: str
        :param throughput: Amount of data transfer throughput, i.e '558 Mbits/sec'
        :type throughput: str
        :param deviation: Percentage of accepted data deviation, i.e '10%'
        :type deviation: str
        """
        self.taf_ue.verify_average_throughput_with_deviation(dt_name, throughput, deviation)

    def change_network_mode(self, network_mode):
        """
        Changes network mode on UE. Detach is performed after the change to ensure
        that UE is not attached.
        :param network_mode: type of network mode to change to e.g. NR_LTE, NR_only, LTE_only
        :type network_mode: str
        :raises IncorrectWidgetText exception when there is no option to select a given network mode
        """
        log_to_console(f"Changing network mode on UE: {self.serial_number} to '{network_mode}'")
        network_mode_switch_method = self._get_ue_details().network_mode_switch_method
        try:
            self.taf_ue.change_network_mode(self.alias, network_mode, network_mode_validation=False,
                                            network_mode_switch_method=network_mode_switch_method)
        except TypeError:
            self.taf_ue.change_network_mode(self.alias, network_mode)
        except RpcError as e:
            if "KeyeventIncorrectLayoutException" in str(e):
                raise IncorrectWidgetText(
                    f"Cannot select given network mode: {network_mode}! Please verify correct value, "
                    f"possible values can be checked in the UE service menu.")
            else:
                raise UnexpectedError(f"Unexpected error occurred when trying to change network mode: {e}")

        self.network_mode = network_mode
        log_to_console("Network mode on UE was set successfully")

    def get_average_throughput(self, dt_name, tput_collection_src="iperf"):
        """
        Method for getting average throughput of data transfer.
        :param dt_name: Data transfer alias
        :type  dt_name: str
        :param tput_collection_src: source of data for counting average throughput
                                    possible sources: iperf, btslog; defaults to iperf
        :type  tput_collection_src: str
        :return: value of average throughput with unit Mbits/sec or Gbits/sec
        """
        tput_avrg = self.taf_ue.get_average_throughput(dt_name, tput_collection_src=tput_collection_src)

        if tput_avrg >= 1000000:
            return f"{round(tput_avrg / 1000000, 3)} Gbits/sec"
        else:
            return f"{round(tput_avrg / 1000)} Mbits/sec"

    def turn_off_airplane_mode(self, timeout=40):
        """
        Turns off airplane mode using the attach method, the direct method is not supported by TAF.
        :param timeout: Timeout for attach operation in seconds
        :type timeout: int
        """
        extra_params = self._get_extra_params_for_ue_attach()

        try:
            self.taf_ue.attach_ue(self.alias, timeout=timeout, **extra_params)
        except CannotAttachError:
            pass
        except RpcError as e:
            if "CannotAttachError" not in str(e):
                raise UnexpectedError(f"Unexpected error occurred when trying to turns off airplane mode\n{str(e)}")

    def _get_ue_details(self):
        return BuiltIn().get_variable_value("${{tl.ues[{}]}}".format(self.index - 1))

    def _get_ue_data_transfer_alias(self, direction):
        return "_".join(["DT", str(self.index), direction])

    def _get_ue_info(self):
        return self.taf_ue.get_ue_info(self.alias)

    def _get_apn_from_ue_info(self, ue_ips_info):
        return next(iter(ue_ips_info)).split('/')[0]

    def _get_extra_params_for_ue_attach(self):
        extra_params = {}
        if "BG95" in self.device_model or "BG96" in self.device_model:
            extra_params["attach_via_fun_lev"] = True

        return extra_params
